const { chromium } = require(process.env.QA_PLAYWRIGHT_PATH || 'playwright');
const assert = require('node:assert/strict');
const base = process.env.QA_BASE_URL || 'http://127.0.0.1:5191';

(async () => {
  const browser = await chromium.launch({ headless: true, channel: 'msedge' });
  try {
    for (const width of [320, 390, 1280]) {
      const page = await browser.newPage({ viewport: { width, height: 650 } });
      await page.goto(base + '/equipos/demo_home?vista=plantilla');
      // Use the actual roster URL generated by the navigation control.
      await page.getByRole('navigation', { name: 'Vistas del equipo' }).getByRole('link', { name: 'Plantilla', exact: true }).click();
      const player = page.getByRole('link', { name: 'Andrea Demo', exact: true });
      await player.waitFor();
      await player.scrollIntoViewIfNeeded();
      const before = await page.evaluate(() => scrollY);
      const url = page.url();
      await player.click();
      await page.getByRole('heading', { name: 'Andrea Demo', exact: true }).waitFor();
      await page.goBack();
      await player.waitFor();
      await page.waitForFunction(y => Math.abs(scrollY - y) < 3, before);
      assert.equal(page.url(), url);
      await page.goForward();
      await page.getByRole('heading', { name: 'Andrea Demo', exact: true }).waitFor();
      await page.goto(base + '/estadisticas?equipo=demo_home&metrica=touchdowns&origen=prueba');
      const rankedPlayer = page.getByRole('link', { name: /Andrea Demo/ }).first();
      await rankedPlayer.waitFor();
      await rankedPlayer.scrollIntoViewIfNeeded();
      const rankingY = await page.evaluate(() => scrollY);
      const rankingUrl = page.url();
      await rankedPlayer.click();
      await page.getByRole('heading', { name: 'Andrea Demo', exact: true }).waitFor();
      await page.goBack();
      await rankedPlayer.waitFor();
      await page.waitForFunction(y => Math.abs(scrollY - y) < 3, rankingY);
      assert.equal(page.url(), rankingUrl);
      assert.equal(await page.getByLabel('Equipo', { exact: true }).inputValue(), 'demo_home');
      assert.equal(await page.getByLabel('Estadística', { exact: true }).inputValue(), 'touchdowns');
      await page.goto(base + '/jornada/demo_finished?estado=WALKOVER&agrupar=cancha');
      await page.getByLabel('Estado', { exact: true }).waitFor();
      assert.equal(await page.getByLabel('Estado', { exact: true }).inputValue(), 'WALKOVER');
      assert.equal(await page.getByLabel('Estado', { exact: true }).locator('option').count(), 7);
      await page.getByLabel('Estado', { exact: true }).selectOption('CANCELLED');
      await page.reload();
      await page.getByLabel('Estado', { exact: true }).waitFor();
      assert.equal(await page.getByLabel('Estado', { exact: true }).inputValue(), 'CANCELLED');
      assert.equal(await page.getByLabel('Agrupar por', { exact: true }).inputValue(), 'cancha');
      const response = await page.request.get(base + '/api/v1/public/games/demo_final');
      const actual = await response.json();
      for (const [status, label] of Object.entries({ SCHEDULED: 'Programado', LIVE: 'En vivo', FINISHED: 'Final', WALKOVER: 'Incomparecencia', POSTPONED: 'Pospuesto', CANCELLED: 'Cancelado' })) {
        await page.route('**/public/games/demo_final', route => route.fulfill({ json: { ...actual, data: { ...actual.data, status, statistics_status: 'PENDING' } } }));
        await page.goto(base + '/partido/demo_final');
        await page.locator('main .badge').filter({ hasText: new RegExp(`^${label}$`) }).waitFor();
        if (['SCHEDULED', 'POSTPONED', 'CANCELLED'].includes(status)) {
          assert.ok(!(await page.locator('main').textContent()).includes('pendientes de captura'));
          assert.equal(await page.getByLabel('Sin marcador', { exact: true }).textContent(), 'VS');
        }
        assert.equal(await page.evaluate(() => document.documentElement.scrollWidth > innerWidth + 1), false);
        await page.unroute('**/public/games/demo_final');
      }
      console.log(`PASS ${width}: historial, plantilla, desplazamiento y seis estados deportivos.`);
      await page.close();
    }
  } finally { await browser.close(); }
})().catch(error => { console.error(error); process.exitCode = 1; });
